using System;
using System.IO;
using System.Linq;
using USB512_interface;
internal static class NpFirstSyncSdGrid16Tests {
    const string Uid="001A0004434250062039314E";const ulong Token=0x1020304050607080UL;
    static int checks;static BinaryWriter vectors;
    static void Need(bool b,string why){checks++;if(!b)throw new Exception(why);}
    static void Put(byte[] b,int at,uint n){Buffer.BlockCopy(BitConverter.GetBytes(n),0,b,at,4);}
    static void Seal(byte[] b){Put(b,60,NpFirstSyncWire.Crc(b,60));}
    static byte[] Legacy(int family,bool scheduled=false){var b=new byte[64];Put(b,0,family==1?0x31444c4eU:0x32444c4eU);Put(b,4,(uint)family);Put(b,8,scheduled?4U:2U);Put(b,12,57);Put(b,16,family==1?3U:7U);Put(b,20,20000);if(family==1){Put(b,24,8192);Put(b,28,0x12344000);Put(b,32,0x12345);Put(b,36,1);}else{Put(b,24,12345);if(scheduled)Buffer.BlockCopy(BitConverter.GetBytes(1793200000123456UL),0,b,28,8);}Seal(b);return b;}
    static byte[] Alter(byte[] b,int at,uint n){var c=(byte[])b.Clone();Put(c,at,n);Seal(c);return c;}
    static byte[] Pair(byte[] a,byte[] q){return a.Concat(q).ToArray();}
    static NpFirstSyncSdReply R(uint features=25,uint supported=29,uint result=0){return new NpFirstSyncSdReply{Result=result,Supported=supported,RecordFeatures=features,Session=features==0?0U:100U,Generation=features==0?0U:9U,SourceEpoch=features==0?0U:11U,ProfileCrc=uint.MaxValue};}
    static bool Accept(int kind,int family,byte[] b){try{if(kind==0)return NpFirstSyncSd.ParseRequest(b,family,Uid).Version==4;var a=b.Take(64).ToArray();var q=b.Skip(64).ToArray();return NpFirstSyncSd.ParseReply(a,q,family).Version==4;}catch(InvalidDataException){return false;}}
    static void V(int kind,int family,byte[] b,bool expected,string why){Need(Accept(kind,family,b)==expected,why);vectors.Write((byte)kind);vectors.Write((byte)family);vectors.Write((byte)(expected?1:0));vectors.Write((byte)0);vectors.Write(b.Length);vectors.Write(b);}
    static void LegacyGoldens(){
        {var q=NpFirstSyncSd.WrapLegacy(Legacy(1),1,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAEAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBADAAAAIE4AAAAgAAAAQDQSRSMBAAEAAAAAAAAATCzfSg==","legacy1 request byte golden family1");var a=NpFirstSyncSd.BuildReply(q,1,R(1U,5U));Need(Convert.ToBase64String(a)=="TlBTQQEAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAABQAAAAEAAABkAAAACQAAAAsAAAD/////UvarRA==","legacy1 reply byte golden family1");Need(!NpFirstSyncSd.ParseReply(a,q,1).Grid16,"old version is never grid16 opt-in");}
        {var q=NpFirstSyncSd.WrapLegacyFineAux(Legacy(1),1,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAIAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBADAAAAIE4AAAAgAAAAQDQSRSMBAAEAAAAAAAAANRhgbA==","legacy2 request byte golden family1");var a=NpFirstSyncSd.BuildReply(q,1,R(9U,13U));Need(Convert.ToBase64String(a)=="TlBTQQIAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAADQAAAAkAAABkAAAACQAAAAsAAAD/////JyjCLQ==","legacy2 reply byte golden family1");Need(!NpFirstSyncSd.ParseReply(a,q,1).Grid16,"old version is never grid16 opt-in");}
        {var q=NpFirstSyncSd.WrapLegacyFineCounter64(Legacy(1),1,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAMAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBADAAAAIE4AAAAgAAAAQDQSRSMBAAEAAAAAAAAA4gv1cQ==","legacy3 request byte golden family1");var a=NpFirstSyncSd.BuildReply(q,1,R(25U,29U));Need(Convert.ToBase64String(a)=="TlBTQQMAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAAHQAAABkAAABkAAAACQAAAAsAAAD/////6O/6rw==","legacy3 reply byte golden family1");Need(!NpFirstSyncSd.ParseReply(a,q,1).Grid16,"old version is never grid16 opt-in");}
        {var q=NpFirstSyncSd.WrapLegacy(Legacy(2),2,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAEAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAHAAAAIE4AADkwAAAAAAAAAAAAAAAAAAAAAAAAPRTAZQ==","legacy1 request byte golden family2");var a=NpFirstSyncSd.BuildReply(q,2,R(1U,7U));Need(Convert.ToBase64String(a)=="TlBTQQEAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAABwAAAAEAAABkAAAACQAAAAsAAAD/////XTqQnQ==","legacy1 reply byte golden family2");Need(!NpFirstSyncSd.ParseReply(a,q,2).Grid16,"old version is never grid16 opt-in");}
        {var q=NpFirstSyncSd.WrapLegacyFineAux(Legacy(2),2,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAIAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAHAAAAIE4AADkwAAAAAAAAAAAAAAAAAAAAAAAARCB/Qw==","legacy2 request byte golden family2");var a=NpFirstSyncSd.BuildReply(q,2,R(9U,15U));Need(Convert.ToBase64String(a)=="TlBTQQIAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAADwAAAAkAAABkAAAACQAAAAsAAAD/////KOT59A==","legacy2 reply byte golden family2");Need(!NpFirstSyncSd.ParseReply(a,q,2).Grid16,"old version is never grid16 opt-in");}
        {var q=NpFirstSyncSd.WrapLegacyFineCounter64(Legacy(2),2,Uid,Token);Need(Convert.ToBase64String(q)=="TlBTRAMAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAHAAAAIE4AADkwAAAAAAAAAAAAAAAAAAAAAAAAkzPqXg==","legacy3 request byte golden family2");var a=NpFirstSyncSd.BuildReply(q,2,R(25U,31U));Need(Convert.ToBase64String(a)=="TlBTQQMAAQA5AAAABAAaAAZQQkNOMTkggHBgUEAwIBAAAAAAHwAAABkAAABkAAAACQAAAAsAAAD/////5yPBdg==","legacy3 reply byte golden family2");Need(!NpFirstSyncSd.ParseReply(a,q,2).Grid16,"old version is never grid16 opt-in");}
    }
    static void Generate(string p){using(vectors=new BinaryWriter(File.Create(p))){LegacyGoldens();var legacy=Legacy(2);byte[] start=NpFirstSyncSd.WrapLegacyGrid16(legacy,2,Uid,Token),caps=NpFirstSyncSd.QueryGrid16(0,99,2,Uid),status=NpFirstSyncSd.QueryGrid16(2,100,2,Uid,Token);
        foreach(var q in new[]{start,caps,status}){V(0,2,q,true,"v4 known shape");V(0,1,q,false,"V1 rejects v4");V(0,2,Alter(q,4,(BitConverter.ToUInt32(q,4)&0xffff0000U)|5),false,"future version not admitted");for(int i=0;i<64;i++){var b=(byte[])q.Clone();b[i]^=1;V(0,2,b,false,"request CRC");}}
        Need(NpFirstSyncSd.Unwrap(start,2,Uid).SequenceEqual(legacy),"v4 exact legacy28 payload");Need(NpFirstSyncSd.FreshStart(start,2,Uid,Token-1)&&!NpFirstSyncSd.FreshStart(start,2,Uid,Token),"v4 fresh token");Need(NpFirstSyncSd.CachedDuplicate(start,(byte[])start.Clone(),2,Uid)&&!NpFirstSyncSd.CachedDuplicate(Alter(start,8,58),start,2,Uid),"v4 exact cached duplicate only");
        foreach(var q in new[]{caps,status,start}){var a=NpFirstSyncSd.BuildReply(q,2,R(q==caps?0U:25U));V(1,2,Pair(a,q),true,"v4 association");V(1,1,Pair(a,q),false,"V1 rejects v4 reply");for(int i=0;i<64;i++){var bad=(byte[])a.Clone();bad[i]^=1;V(1,2,Pair(bad,q),false,"reply CRC");}if(q!=caps){var r=NpFirstSyncSd.ParseReply(a,q,2);Need(r.Associated&&r.FineCounter64&&r.Grid16,"v4 clock+carrier declaration");}}
        var ack=NpFirstSyncSd.BuildReply(start,2,R());foreach(uint feature in new uint[]{0,1,9,24,57})V(1,2,Pair(Alter(ack,40,feature),start),false,"record25 exactly");foreach(uint support in new uint[]{0,1,5,13,16,25,28,32,61})V(1,2,Pair(Alter(ack,36,support),start),false,"v4 support requires29 known bits");
        var scheduled=NpFirstSyncSd.WrapLegacyGrid16(Legacy(2,true),2,Uid,Token);V(0,2,scheduled,true,"scheduled shape V2");var sa=NpFirstSyncSd.BuildReply(scheduled,2,R(25,31));V(1,2,Pair(sa,scheduled),true,"scheduled support bit2");V(1,2,Pair(Alter(sa,36,29),scheduled),false,"scheduled must be advertised");
        var pending=R();pending.Session=pending.Generation=pending.SourceEpoch=0;Need(NpFirstSyncSd.ParseReply(NpFirstSyncSd.BuildReply(start,2,pending),start,2).Associated,"queued association does not assert capture");
        for(uint error=1;error<=5;error++){var er=NpFirstSyncSd.BuildReply(caps,2,R(0,0,error));V(1,2,Pair(er,caps),true,"unsupported context-free error");V(1,2,Pair(Alter(er,44,100),caps),false,"error cannot leak context");}
        foreach(int at in new[]{8,12,32,36,52})V(0,2,Alter(start,at,0),at==52,"identity/profile/token/reserved");V(0,2,Alter(start,52,1),false,"V2 reserved payload");var zeroToken=(byte[])start.Clone();Array.Clear(zeroToken,24,8);Seal(zeroToken);V(0,2,zeroToken,false,"all-zero record token");
    }Console.WriteLine("PASS "+checks+" explicit V2 SD16/v4 and exact legacy1-3 checks");}
    static void Native(string path){var b=File.ReadAllBytes(path);Need(b.Length==128,"C golden extent");var q=b.Take(64).ToArray();var a=b.Skip(64).ToArray();Need(q.SequenceEqual(NpFirstSyncSd.WrapLegacyGrid16(Legacy(2),2,Uid,Token)),"actual C v4 request bytes");Need(a.SequenceEqual(NpFirstSyncSd.BuildReply(q,2,R())),"actual C v4 record25 reply bytes");var parsed=NpFirstSyncSd.ParseReply(a,q,2);Need(parsed.Grid16&&parsed.FineCounter64&&parsed.Session==100,"actual C v4 binding");Console.WriteLine("PASS actual C v4/record25 golden exact UID/token roundtrip");}
    static int Main(string[] args){try{if(args[0]=="generate")Generate(args[1]);else Native(args[1]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
